from decimal import Decimal, ROUND_HALF_EVEN, localcontext


def precise_divide(a, b, places=10):
    with localcontext() as ctx:
        ctx.prec = places + 5
        result = Decimal(str(a)) / Decimal(str(b))
        return round(result, places)


def money_add(amounts):
    total = sum(Decimal(a) for a in amounts)
    return str(total)


def round_half_even(value, places):
    d = Decimal(str(value))
    quantize_str = "0." + "0" * places
    return float(d.quantize(Decimal(quantize_str), rounding=ROUND_HALF_EVEN))


def compare_float_decimal(a, b):
    float_sum = a + b
    decimal_sum = Decimal(str(a)) + Decimal(str(b))
    return {
        "float_sum": float_sum,
        "decimal_sum": str(decimal_sum),
        "equal": Decimal(str(float_sum)) == decimal_sum,
    }
